import express, { Request, Response, NextFunction } from 'express';
import { randomUUID } from 'node:crypto';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { createRemoteJWKSet, jwtVerify } from 'jose';
import { z } from 'zod';

const BIND_HOST = process.env.NODE_ENV === 'production' ? '127.0.0.1' : '127.0.0.1';
const PORT = Number(process.env.MCP_PORT || 3400);
const RESOURCE_URI = process.env.MCP_RESOURCE_URI || 'https://mcp.domation.internal/erp-misa';
const AUTH_ISSUER = process.env.OAUTH_ISSUER || 'https://auth.domation.internal';
const ALLOWED_ORIGINS = new Set(['https://app.domation.net', 'http://127.0.0.1:3000']);
const JWKS = createRemoteJWKSet(new URL(`${AUTH_ISSUER}/.well-known/jwks.json`));

interface VerifiedTenantContext {
  tenantId: string;
  subject: string;
  scopes: string[];
}

// 1. Bat buoc xac thuc Origin header de chan DNS Rebinding
function enforceOriginCheck(req: Request, res: Response, next: NextFunction) {
  const origin = req.headers.origin;
  if (origin && !ALLOWED_ORIGINS.has(origin)) {
    res.status(403).json({ error: 'forbidden_origin', message: 'Origin not allowlisted' });
    return;
  }
  next();
}

// 2. OAuth 2.1 Resource Server: RFC 9728 (401 WWW-Authenticate) + RFC 8707 (aud check)
async function requireOAuth21(req: Request, res: Response, next: NextFunction) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) {
    res.setHeader(
      'WWW-Authenticate',
      `Bearer resource_metadata="${RESOURCE_URI}/.well-known/oauth-protected-resource"`
    );
    res.status(401).json({ error: 'unauthorized' });
    return;
  }

  const token = auth.slice('Bearer '.length).trim();
  try {
    const { payload } = await jwtVerify(token, JWKS, {
      issuer: AUTH_ISSUER,
      audience: RESOURCE_URI, // RFC 8707: khoa dung aud, cam Token Passthrough
    });
    const scopes = String(payload.scope || '').split(' ').filter(Boolean);
    const tenantId = String(payload.tenant_id || '');
    if (!tenantId) {
      res.status(403).json({ error: 'missing_tenant_claim' });
      return;
    }
    (req as Request & { authCtx?: VerifiedTenantContext }).authCtx = {
      tenantId,
      subject: String(payload.sub || ''),
      scopes,
    };
    next();
  } catch {
    res.status(401).json({ error: 'invalid_or_wrong_audience_token' });
  }
}

function buildMcpServer(authCtx: VerifiedTenantContext): McpServer {
  const server = new McpServer({ name: 'domation-erp-misa-mcp', version: '2.1.0' });

  server.registerTool(
    'crm_misa_reconcile_invoice',
    {
      description: 'Doi soat cong no hoa don MISA voi don hang CRM theo dung tenantId duoc cap phep.',
      inputSchema: {
        orderCode: z.string().regex(/^ORD-[A-Z0-9-]{4,24}$/),
      },
    },
    async ({ orderCode }) => {
      if (!authCtx.scopes.includes('misa:ledger:read')) {
        return {
          isError: true,
          content: [{ type: 'text', text: 'Thieu scope misa:ledger:read trong OAuth 2.1 token.' }],
        };
      }
      // Dung MISA credential noi bo rieng theo tenantId thay vi pass-through token cua user
      const reconciliation = await queryInternalMisaAndCrm(authCtx.tenantId, orderCode);
      return { content: [{ type: 'text', text: JSON.stringify(reconciliation) }] };
    }
  );
  return server;
}

async function queryInternalMisaAndCrm(tenantId: string, orderCode: string) {
  return {
    tenantId,
    orderCode,
    crmStage: 'Hop dong da ky (Pipeline 6/8)',
    misaSyncStatus: 'DA_PHAT_HANH_HDDT',
    outstandingVnd: 0,
  };
}

const app = express();
app.use(express.json({ limit: '512kb' }));
app.use(enforceOriginCheck);

// RFC 9728 Protected Resource Metadata endpoint
app.get('/.well-known/oauth-protected-resource', (_req, res) => {
  res.json({
    resource: RESOURCE_URI,
    authorization_servers: [AUTH_ISSUER],
    scopes_supported: ['crm:lead:read', 'misa:ledger:read', 'misa:voucher:draft'],
    bearer_methods_supported: ['header'],
  });
});

// Single Streamable HTTP endpoint (MCP 2025-11-25)
app.post('/mcp', requireOAuth21, async (req, res) => {
  const authCtx = (req as Request & { authCtx: VerifiedTenantContext }).authCtx;
  const server = buildMcpServer(authCtx);
  const transport = new StreamableHTTPServerTransport({
    sessionIdGenerator: () => randomUUID(),
    enableJsonResponse: true,
  });
  res.on('close', () => {
    transport.close();
    server.close();
  });
  await server.connect(transport);
  await transport.handleRequest(req, res, req.body);
});

// Luon bind 127.0.0.1 phia sau TLS reverse proxy
app.listen(PORT, BIND_HOST, () => {
  console.log(`Streamable HTTP MCP listening at http://${BIND_HOST}:${PORT}/mcp`);
});
